// Step Explorer — renders and filters the step table.
// Data comes from window.STEP_DATA (assets/step-data.js), generated by scan-steps.js.

(function () {
  const data = window.STEP_DATA;
  if (!data) return;

  const steps = data.steps || [];
  const searchInput = document.getElementById('searchInput');
  const typeFilter = document.getElementById('typeFilter');
  const productFilter = document.getElementById('productFilter');
  const dslFilter = document.getElementById('dslFilter');
  const clearBtn = document.getElementById('clearFilters');
  const rows = document.getElementById('stepRows');
  const emptyState = document.getElementById('emptyState');
  const resultCount = document.getElementById('resultCount');

  // Populate the product + DSL dropdowns from the scanned metadata.
  (data.products || []).forEach((p) => productFilter.appendChild(option(p, p)));
  (data.dsls || []).forEach((d) => dslFilter.appendChild(option(d, d)));
  // A bucket for steps that don't reference any DSL directly.
  if (steps.some((s) => !s.dsl || s.dsl.length === 0)) {
    dslFilter.appendChild(option('__none__', '— No DSL —'));
  }

  function option(value, label) {
    const o = document.createElement('option');
    o.value = value;
    o.textContent = label;
    return o;
  }

  function escapeHtml(str) {
    return str.replace(/[&<>"']/g, (c) =>
      ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])
    );
  }

  // Highlight the matched query text (already HTML-escaped input).
  function highlight(escaped, query) {
    if (!query) return escaped;
    const q = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return escaped.replace(new RegExp('(' + q + ')', 'gi'), '<mark>$1</mark>');
  }

  function dslCell(dsl) {
    if (!dsl || dsl.length === 0) return '<span class="dsl-none">—</span>';
    return '<span class="dsl-list">' +
      dsl.map((d) => '<span class="chip">' + escapeHtml(d) + '</span>').join('') +
      '</span>';
  }

  function render() {
    const q = searchInput.value.trim().toLowerCase();
    const type = typeFilter.value;
    const product = productFilter.value;
    const dsl = dslFilter.value;

    const matches = steps.filter((s) => {
      if (type && s.type !== type) return false;
      if (product && s.product !== product) return false;
      if (dsl) {
        if (dsl === '__none__') {
          if (s.dsl && s.dsl.length > 0) return false;
        } else if (!s.dsl || !s.dsl.includes(dsl)) {
          return false;
        }
      }
      if (q && !s.text.toLowerCase().includes(q)) return false;
      return true;
    });

    rows.innerHTML = matches
      .map((s) => {
        const text = highlight(escapeHtml(s.text), q);
        return (
          '<tr>' +
          '<td><span class="type-badge type-' + s.type + '">' + s.type + '</span></td>' +
          '<td class="col-text">' + text + '</td>' +
          '<td><span class="chip">' + escapeHtml(s.product) + '</span></td>' +
          '<td class="col-dsl">' + dslCell(s.dsl) + '</td>' +
          '<td class="col-file">' + escapeHtml(s.file) + '</td>' +
          '</tr>'
        );
      })
      .join('');

    emptyState.hidden = matches.length !== 0;
    resultCount.innerHTML =
      'Showing <strong>' + matches.length + '</strong> of ' + steps.length + ' steps';
  }

  [searchInput, typeFilter, productFilter, dslFilter].forEach((el) =>
    el.addEventListener('input', render)
  );

  clearBtn.addEventListener('click', () => {
    searchInput.value = '';
    typeFilter.value = '';
    productFilter.value = '';
    dslFilter.value = '';
    render();
  });

  render();
})();
